def merge(g,v):
    w=[]
    for lo,hi in g:
        if lo<0: lo=0
        if hi > v-1: hi=v-1
        if lo<=hi: w.append((lo,hi))
    w.sort()
    r=[]
    for lo,hi in w:
        if r and lo<=r[-1][1]+1:
            if hi> r[-1][1]: r[-1][1]=hi
        else:
            r.append([lo,hi])
    return r
def full(ev,k,v):
    ev.sort()
    r=[]
    cur=0
    prev=0
    for pos,dl in ev:
        if cur==k and pos>prev:
            r.append((prev,pos-1))
        cur+=dl
        prev=pos
    if cur==k and v>prev:
        r.append((prev,v-1))
    return r
t=int(input())
for _ in range(t):
    n=int(input())
    a=list(map(int,input().split()))
    b=[[] for _ in range(n+1)]
    for i in range(1,n+1):
        b[a[i-1]].append(i)
    dp=[1]
    for v in range(1,n+1):
        c=b[v]
        nd=[0]*(v+1)
        if not c:
            sg=ug=[(0,v-1)]
        else:
            k=len(c)
            es=[]
            eu=[]
            for i in c:
                h=(i+1)//2 
                q=(n-i+2)//2 
                e=i+v-n
                d=v-q
                ps=[]
                pu=[]
                if e==h:
                    ps.append((0,h-1))
                    pu.append((0,h-1))
                elif e<h:
                    pu.append((h-1,h-1))
                if d==i-1:
                    ps.append((i-1,v))
                    pu.append((i-1,v))
                elif 0<=d <i-1:
                    ps.append((d,d))
                for lo,hi in merge(ps,v):
                    es.append((lo,1));es.append((hi+1,-1))
                for lo,hi in merge(pu,v):
                    eu.append((lo,1)); eu.append((hi+1,-1))
            sg=full(es,k,v)
            ug = full(eu,k,v)
        for lo,hi in sg:
            nd[lo:hi+1]=dp[lo:hi+1]
        for lo,hi in ug:
            nd[lo+1:hi+2]=[(x+y)%M for x,y in zip(nd[lo+1:hi+2],dp[lo:hi+1])]
        dp=nd
    print(sum(dp)%M*((M+1)//2)%M)
